// Port of ~/.claude/statusline.py, plus the mod-only figures: builds the two lines as colored segments.

import { CACHE_ALERT_TOKENS, urgentLeadMs, warnLeadMs } from './cache'
import type { CacheStatus } from './cache'
import { DEFAULT_SETTINGS } from './settings'
import type { Settings } from './settings'

// `press` makes the segment interactive: `model` and `context-label` open /model and /context, `folder` shows and
// copies the path, `usage` and `context` swap to the cost and the token count on a click, `reset` swaps the
// reset countdowns for the clock time of the reset, `cache` toasts the prompt cache's details.
export type Press = 'settings' | 'model' | 'folder' | 'usage' | 'context' | 'context-label' | 'reset' | 'cache' | 'changes'
export type Seg = { text: string; color?: string; bold?: boolean; dim?: boolean; underline?: boolean; press?: Press }

export const C = {
  CY: 'cyan',
  GR: 'green',
  YL: 'yellow',
  OR: '#d77800', // orange (warning)
  RD: 'red',
  BL: '#0891b2', // custom blue
  WH: 'white',
} as const

export const FIVE_HOUR_MS = 5 * 60 * 60 * 1000
export const SEVEN_DAY_MS = 7 * 24 * 60 * 60 * 1000

export type RateLimit = { percentUsed?: number; resetsAt?: string; etaMs?: number }

export type StatusInput = {
  model: string
  effort?: string | null
  cwd: string
  git: {
    repo: string
    branch: string
    changes?: number
    ahead?: number
    behind?: number
    stashes?: number
    conflicts?: number
    operation?: string
  } | null
  contextPercent?: number
  /** Where auto-compaction runs, as a percentage of the context window; absent when it is off. */
  compactAtPercent?: number
  costUsd?: number
  /** A subscription's account: the 5h/7d windows are what limits it, so they stand in for the cost. */
  hasWindows: boolean
  fiveHour?: RateLimit
  sevenDay?: RateLimit
  /** The windows swapped for the API-equivalent cost. */
  showCost?: boolean
  /** The reset countdowns swapped for the clock time of the reset. */
  showResetAt?: boolean
  /** The main conversation's prompt cache; absent before its first model request. */
  cache?: CacheStatus
  /** What /config shows of the band; the defaults when absent. */
  settings?: Settings
  nowMs: number
}

const SEP: Seg = { text: ' │ ', dim: true }

export function fmtDuration(ms: number): string {
  if (!ms) return '--'
  let s = Math.floor(ms / 1000)
  if (s < 60) return `${s}s`
  let m = Math.floor(s / 60)
  s %= 60
  if (m < 60) return `${m}m${String(s).padStart(2, '0')}s`
  const h = Math.floor(m / 60)
  m %= 60
  return `${h}h${String(m).padStart(2, '0')}m`
}

// claude-opus-5-5 -> Opus 5.5, claude-haiku-4-5-20251001 -> Haiku 4.5, a [1m] suffix -> (1M); anything else as given.
export function modelName(id: string): string {
  const m = /^claude-(opus|sonnet|haiku|fable)-(\d+)(?:-(\d{1,2}))?(?:-\d{8})?(\[1m\])?$/i.exec(id)
  if (!m) return id
  const [, family = '', major, minor, isLong] = m
  const name = family.charAt(0).toUpperCase() + family.slice(1).toLowerCase()
  return `${name} ${major}${minor ? '.' + minor : ''}${isLong ? ' (1M)' : ''}`
}

// The band's one button: `Opus 5.5 · medium`, or the model alone before the effort is known.
export function modelEffortLabel(model: string, effort: string | null | undefined): string {
  const name = model ? modelName(model) : '--'
  return effort ? `${name} · ${effort}` : name
}

// Every bar on the band (context, 5h, 7d) has this many cells, so they line up alike.
export const BAR_WIDTH = 10

export function bar(pct: number, width = BAR_WIDTH): string {
  const filled = Math.max(0, Math.min(width, Math.floor((pct * width) / 100)))
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

// The context bar, with a white │ where auto-compaction runs, as the 5h/7d bars mark the time elapsed.
export function contextBar(pct: number, compactAtPercent: number | undefined, color: string, width = BAR_WIDTH): Seg[] {
  const cells = bar(pct, width)
  if (compactAtPercent === undefined) return [{ text: cells, color }]
  const marker = Math.min(width - 1, Math.max(0, Math.floor((compactAtPercent * width) / 100)))
  return [
    ...(marker > 0 ? [{ text: cells.slice(0, marker), color }] : []),
    { text: '│', color: C.WH },
    ...(marker < width - 1 ? [{ text: cells.slice(marker + 1), color }] : []),
  ]
}

function fmtPct(val: number | undefined): string {
  return val === undefined ? '--' : `${val.toFixed(0)}%`
}

// Compact span: 1d02h, 1h30m, 12m.
export function fmtSpan(ms: number): string {
  let m = Math.floor(ms / 60_000)
  let h = Math.floor(m / 60)
  m %= 60
  const d = Math.floor(h / 24)
  h %= 24
  if (d) return `${d}d${String(h).padStart(2, '0')}h`
  if (h) return `${h}h${String(m).padStart(2, '0')}m`
  return `${m}m`
}

export function fmtReset(resetsAtMs: number | undefined, nowMs: number): string {
  if (resetsAtMs === undefined) return ''
  const remaining = Math.floor(resetsAtMs / 1000) - Math.floor(nowMs / 1000)
  if (remaining <= 0) return '↺ now'
  return `↺ ${fmtSpan(remaining * 1000)}`
}

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const

// The reset as a local clock time: 14:00 today, Sat 14:00 within the week, next Wed 14:00 a week on.
export function fmtResetAt(resetsAtMs: number | undefined, nowMs: number): string {
  if (resetsAtMs === undefined) return ''
  if (resetsAtMs <= nowMs) return '↺ now'
  const at = new Date(resetsAtMs)
  const now = new Date(nowMs)
  const time = `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`
  const days = Math.round(
    (new Date(at.getFullYear(), at.getMonth(), at.getDate()).getTime() -
      new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()) /
      86_400_000,
  )
  if (days === 0) return `↺ ${time}`
  return `↺ ${days >= 7 ? 'next ' : ''}${WEEKDAYS[at.getDay()]} ${time}`
}

export function parseReset(resetsAt: string | undefined): number | undefined {
  const ms = resetsAt ? Date.parse(resetsAt) : NaN
  return Number.isNaN(ms) ? undefined : ms
}

export function windowFraction(resetsAtMs: number | undefined, windowMs: number, nowMs: number): number | undefined {
  if (resetsAtMs === undefined) return undefined
  const start = resetsAtMs - windowMs
  if (nowMs <= start) return 0
  if (nowMs >= resetsAtMs) return 1
  return (nowMs - start) / windowMs
}

// Blue: at or below the time-elapsed pace; orange: ahead of pace; red: >= 80% consumed.
export function rateLimitColor(usedPct: number | undefined, elapsed: number | undefined): string {
  if (usedPct === undefined) return C.BL
  if (usedPct >= 80) return C.RD
  if (elapsed !== undefined && usedPct > elapsed * 100) return C.OR
  return C.BL
}

// The projection warns only when 100% comes this soon, as a fraction of the time left to the reset.
export const PROJECTION_WARN_FRACTION = 0.6

/**
 * Time from now until the window reaches 100% at its average rate so far (a rule of three:
 * used% over the time elapsed since the window opened), or undefined when at that pace it
 * would not get there within PROJECTION_WARN_FRACTION of the time left to the reset, or
 * nothing is used yet.
 */
export function projectByPace(
  usedPct: number | undefined,
  resetsAtMs: number | undefined,
  windowMs: number,
  nowMs: number,
): number | undefined {
  if (usedPct === undefined || usedPct <= 0 || usedPct >= 100 || resetsAtMs === undefined) return undefined
  const elapsedMs = nowMs - (resetsAtMs - windowMs)
  if (elapsedMs <= 0 || nowMs >= resetsAtMs) return undefined
  const etaMs = (elapsedMs * (100 - usedPct)) / usedPct
  return etaMs < PROJECTION_WARN_FRACTION * (resetsAtMs - nowMs) ? etaMs : undefined
}

export function rateLimitBar(usedPct: number | undefined, elapsed: number | undefined, color: string, width = BAR_WIDTH): Seg[] {
  const used = usedPct === undefined ? 0 : Math.max(0, Math.min(100, Math.round(usedPct)))
  const filled = Math.max(0, Math.min(width, Math.floor((used * width) / 100)))
  const marker = elapsed === undefined ? undefined : Math.min(width - 1, Math.max(0, Math.floor(elapsed * width)))
  const segs: Seg[] = []
  for (let i = 0; i < width; i++) {
    if (i === marker) segs.push({ text: '│', color: C.WH })
    else if (i < filled) segs.push({ text: '█', color })
    else segs.push({ text: '░', dim: true })
  }
  return segs
}

// The window's color as statusline.py picks it, the reset-now case included.
export function windowColor(rl: RateLimit | undefined, windowMs: number, nowMs: number): string {
  const resetsAtMs = parseReset(rl?.resetsAt)
  const isResetNow = resetsAtMs !== undefined && resetsAtMs <= nowMs
  if (isResetNow) return rateLimitColor(undefined, undefined)
  return rateLimitColor(rl?.percentUsed, windowFraction(resetsAtMs, windowMs, nowMs))
}

function rateLimitSegs(label: string, rl: RateLimit | undefined, windowMs: number, nowMs: number, showResetAt = false): Seg[] {
  const used = rl?.percentUsed
  const resetsAtMs = parseReset(rl?.resetsAt)
  // When the window has fully elapsed, zero out both fill and marker.
  const isResetNow = resetsAtMs !== undefined && resetsAtMs <= nowMs
  const elapsed = windowFraction(resetsAtMs, windowMs, nowMs)
  const color = windowColor(rl, windowMs, nowMs)
  const reset = showResetAt ? fmtResetAt(resetsAtMs, nowMs) : fmtReset(resetsAtMs, nowMs)
  const eta = isResetNow ? undefined : rl?.etaMs
  // The spaces between the clickable stretches stay out of them, so the pointer lights the text alone.
  const usage = (segs: Seg[]) => segs.map(seg => ({ ...seg, press: 'usage' as const }))
  return [
    ...usage([
      { text: `${label} ` },
      ...rateLimitBar(isResetNow ? 0 : used, isResetNow ? undefined : elapsed, color),
      { text: ' ' },
      { text: fmtPct(used), color },
    ]),
    ...(reset ? [{ text: ' ' }, { text: reset, dim: true, press: 'reset' as const }] : []),
    ...(eta !== undefined ? [{ text: ' ' }, ...usage([{ text: `⚠ 100% in ${fmtSpan(eta)}`, color: C.RD, bold: true }])] : []),
  ]
}

// What the session has cost: what an API account pays.
export function costSegs(costUsd: number | undefined): Seg[] {
  return [{ text: 'cost ' }, { text: `$${(costUsd ?? 0).toFixed(2)}`, color: C.YL }]
}

// On a subscription, a click on the windows swaps them for what the session would cost on the API.
function contextColor(pct: number): string {
  return pct >= 85 ? C.RD : pct >= 70 ? C.YL : C.GR
}

// 950 -> 950, 358700 -> 358.7k, 200000 -> 200k, 1000000 -> 1M.
export function fmtTokens(n: number): string {
  const trim = (x: number) => x.toFixed(1).replace(/\.0$/, '')
  if (n >= 1_000_000) return `${trim(n / 1_000_000)}M`
  if (n >= 1_000) return `${trim(n / 1_000)}k`
  return String(Math.round(n))
}

// A click on the context bar swaps it for the tokens in use out of the window: 358.7k / 1M.
export function contextAltSegs(percent: number | undefined, tokens: number | undefined, window: number): Seg[] {
  const color = contextColor(Math.round(percent ?? 0))
  return [{ text: ' ' }, { text: `${fmtTokens(tokens ?? 0)} / ${fmtTokens(window)}`, color }]
}

export function costAltSegs(costUsd: number | undefined): Seg[] {
  return [{ text: 'cost ≈ ' }, { text: `$${(costUsd ?? 0).toFixed(2)}`, color: C.YL }, { text: ' API-equivalent', dim: true }]
}

/**
 * Whether the account is one with 5h/7d windows, from what was known before and what the
 * engine reports now: windows mark it as one; a model response of this session that came back
 * without them marks it as not, as when an API key replaces the subscription; before any
 * response nothing changes (the context's tokens are no sign: the desktop counts them at once).
 */
export function accountHasWindows(wasKnown: boolean, rateLimitCount: number, hasResponded: boolean): boolean {
  if (rateLimitCount > 0) return true
  if (hasResponded) return false
  return wasKnown
}

// Minutes while there are ten or more, then minutes and seconds: 42m, 4m30s, 45s.
function fmtLeft(ms: number): string {
  return ms >= 10 * 60_000 ? `${Math.floor(ms / 60_000)}m` : fmtDuration(Math.max(1000, ms))
}

// The prompt cache beside the context it holds: its countdown, green, yellow near the end and red
// when the expiry toast is due; once it lapsed, cold, orange when the prefix is large.
export function cacheSegs(c: CacheStatus): Seg {
  if (c.remainingMs <= 0) {
    return c.tokens >= CACHE_ALERT_TOKENS ? { text: '○ cold', color: C.OR } : { text: '○ cold', dim: true }
  }
  const color = c.remainingMs <= urgentLeadMs(c.ttlMs) ? C.RD : c.remainingMs <= warnLeadMs(c.ttlMs) ? C.YL : C.GR
  return { text: `● ${fmtLeft(c.remainingMs)}`, color }
}

// The windows the account reports: some plans have a 5h window and no weekly one. Before the
// first response tells which, both stand as placeholders.
function windowsSegs(s: StatusInput): Seg[] {
  const isKnown = s.fiveHour !== undefined || s.sevenDay !== undefined
  const shown = [
    ...(!isKnown || s.fiveHour ? [rateLimitSegs('5h', s.fiveHour, FIVE_HOUR_MS, s.nowMs, s.showResetAt)] : []),
    ...(!isKnown || s.sevenDay ? [rateLimitSegs('7d', s.sevenDay, SEVEN_DAY_MS, s.nowMs, s.showResetAt)] : []),
  ]
  return shown.flatMap((segs, i) => (i === 0 ? segs : [SEP, ...segs]))
}

// The windows, which a click swaps for the cost, or the cost alone; `auto` picks by the account.
function usageSegs(s: StatusInput, usage: Settings['usage']): Seg[] {
  if (usage === 'off') return []
  const hasWindows = usage === 'auto' ? s.hasWindows : usage === 'rate-limits'
  if (!hasWindows) return [SEP, ...costSegs(s.costUsd)]
  if (s.showCost) return [SEP, ...costAltSegs(s.costUsd).map(seg => ({ ...seg, press: 'usage' as const }))]
  return [SEP, ...windowsSegs(s)]
}

export function buildLines(s: StatusInput): [Seg[], Seg[]] {
  const settings = s.settings ?? DEFAULT_SETTINGS
  const isFull = settings.git === 'full'
  const cwdN = s.cwd.replace(/\\/g, '/')
  const folder = cwdN.replace(/\/+$/, '').split('/').pop() || cwdN

  const gitSegs: Seg[] = s.git && settings.git !== 'off'
    ? [
        { text: '⎇  ', color: C.GR, press: 'folder' },
        { text: s.git.repo, color: C.GR, bold: true, press: 'folder' },
        { text: ':', dim: true, press: 'folder' },
        { text: s.git.branch, color: C.YL, press: 'folder' },
        // An operation git left under way, and the files it left in conflict.
        ...(s.git.operation ? [{ text: ` ${s.git.operation}`, color: C.RD, bold: true }] : []),
        ...(s.git.conflicts ? [{ text: ` ✖${s.git.conflicts}`, color: C.RD }] : []),
        // Files changed (a click shows their diff), commits not yet pushed and not yet pulled, then
        // the stashes kept, quiet: a reminder, not a state of the branch.
        ...(isFull && s.git.changes ? [{ text: ' ' }, { text: `●${s.git.changes}`, color: C.OR, press: 'changes' as const }] : []),
        ...(isFull && s.git.ahead ? [{ text: ` ↑${s.git.ahead}`, color: C.CY }] : []),
        ...(isFull && s.git.behind ? [{ text: ` ↓${s.git.behind}`, color: C.CY }] : []),
        ...(isFull && s.git.stashes ? [{ text: ` ≡${s.git.stashes}`, dim: true }] : []),
      ]
    : // The icon apart from the name: the name inverts under the pointer, the icon shows the path.
      [
        { text: '📁 ', dim: true, press: 'folder' },
        { text: folder, dim: true, press: 'folder' },
      ]

  const line1: Seg[] = [
    // The diamond opens the band's settings.
    { text: '◆', color: C.CY, bold: true, press: 'settings' },
    { text: ' ' },
    { text: modelEffortLabel(s.model, s.effort), color: C.CY, bold: true, press: 'model' },
    SEP,
    ...gitSegs,
  ]

  // Rounded, as /context rounds it, so both read the same figure.
  const pct = Math.round(s.contextPercent ?? 0)
  const ctxColor = contextColor(pct)

  const line2: Seg[] = [
    { text: 'ctx', press: 'context-label' },
    { text: ' ' },
    ...contextBar(pct, s.compactAtPercent, ctxColor).map(seg => ({ ...seg, press: 'context' as const })),
    { text: ' ', press: 'context' },
    { text: `${pct}%`, color: ctxColor, press: 'context' },
    ...(s.cache && settings.cache !== 'off' ? [{ text: ' ' }, { ...cacheSegs(s.cache), press: 'cache' as const }] : []),
    ...usageSegs(s, settings.usage),
  ]

  return [line1, line2]
}

files.hooks/effort.ts:
// Reading the level a /effort run set.

// What /effort accepts ("Valid options are: low, medium, high, xhigh, max, auto").
export const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max', 'auto'] as const

/**
 * The level a finished /effort set: what its output reports ("Set effort level to high ..."),
 * else the level its args named (the output may not reach hooks); undefined for an unknown level or none.
 */
export function effortFromCommand(args: string, output: string | undefined): string | undefined {
  const reported = /^Set effort level to (\w+)/.exec(output ?? '')?.[1]
  if (reported) return reported
  const asked = args.trim().split(/\s+/)[0] ?? ''
  return (EFFORTS as readonly string[]).includes(asked) ? asked : undefined
}

/**
 * The effort a finished /model left the session on: `null` when it set a model with no effort
 * ("Set model to `Haiku 4.5` ..."), the level it names ("... with `medium` effort"), and
 * undefined when it changed nothing ("Kept model as ...", "Cancelled") or the output is unknown.
 */
export function effortFromModelCommand(output: string | undefined): string | null | undefined {
  if (!output || !/^Set model to /.test(output)) return undefined
  return /with `(\w+)` effort/.exec(output)?.[1] ?? null
}

