// Reading `git status --porcelain=v2 --branch --show-stash`: the branch, the files changed, the
// commits ahead of and behind its upstream, and the stashes kept.

export type GitStatus = { branch: string; changes: number; ahead: number; behind: number; stashes: number; conflicts: number }

export function parseGitStatus(stdout: string): GitStatus {
  let head = ''
  let oid = ''
  let ahead = 0
  let behind = 0
  let stashes = 0
  let changes = 0
  let conflicts = 0
  for (const line of stdout.split(/\r?\n/)) {
    if (!line) continue
    if (line.startsWith('# branch.head ')) head = line.slice('# branch.head '.length)
    else if (line.startsWith('# branch.oid ')) oid = line.slice('# branch.oid '.length)
    else if (line.startsWith('# branch.ab ')) {
      const ab = /\+(\d+) -(\d+)/.exec(line)
      ahead = Number(ab?.[1] ?? 0)
      behind = Number(ab?.[2] ?? 0)
    } else if (line.startsWith('# stash ')) {
      // Only when there is one: `# stash 2`.
      stashes = Number(line.slice('# stash '.length)) || 0
    } else if (!line.startsWith('#')) {
      changes += 1
      // `u`: a file a merge, rebase or cherry-pick left in conflict.
      if (line.startsWith('u ')) conflicts += 1
    }
  }
  // A detached HEAD reads as its short sha, as `rev-parse --short` gives it.
  const branch = head === '(detached)' ? `#${oid.slice(0, 7)}` : head
  return { branch, changes, ahead, behind, stashes, conflicts }
}

export type GitOperation = { operation: string; branch?: string }
export type GitDirReader = { exists: (path: string) => Promise<boolean>; read: (path: string) => Promise<string> }

/**
 * An operation git left under way, named as git's own prompt names it, from the files it keeps
 * in the git folder; a rebase also says the branch it rebases, since HEAD is detached meanwhile.
 */
export async function readOperation(gitDir: string, dir: GitDirReader): Promise<GitOperation | null> {
  const at = (name: string) => `${gitDir}/${name}`
  const text = (name: string) => dir.read(at(name)).then(t => t.trim(), () => '')
  const rebases = [
    ['rebase-merge', 'msgnum', 'end'],
    ['rebase-apply', 'next', 'last'],
  ] as const
  for (const [folder, step, total] of rebases) {
    if (!(await dir.exists(at(folder)))) continue
    const isAm = folder === 'rebase-apply' && (await dir.exists(at(`${folder}/applying`)))
    const [n, m, head] = await Promise.all([text(`${folder}/${step}`), text(`${folder}/${total}`), text(`${folder}/head-name`)])
    const progress = n && m ? ` ${n}/${m}` : ''
    const branch = head.startsWith('refs/heads/') ? head.slice('refs/heads/'.length) : undefined
    return { operation: `${isAm ? 'AM' : 'REBASING'}${progress}`, ...(branch && { branch }) }
  }
  const marks = [
    ['MERGE_HEAD', 'MERGING'],
    ['CHERRY_PICK_HEAD', 'CHERRY-PICKING'],
    ['REVERT_HEAD', 'REVERTING'],
    ['BISECT_LOG', 'BISECTING'],
  ] as const
  for (const [file, operation] of marks) if (await dir.exists(at(file))) return { operation }
  return null
}

files.hooks/changes.ts:
// Reading `git diff HEAD` into the files the changes pane shows: each one's status, the lines
// added and removed, and its hunks, whole hunks only (a hunk cut short draws as no diff).

import type { ChangedFile } from '../types'

// What the pane draws of the hunks, in all; past it the rest of the files list without them.
export const DIFF_LIMIT = 80_000

export function parseDiff(stdout: string, limit = DIFF_LIMIT): { files: ChangedFile[]; isCut: boolean } {
  const files: ChangedFile[] = []
  let used = 0
  let isCut = false
  const chunks = stdout.split(/^(?=diff --git )/m).filter(chunk => chunk.startsWith('diff --git '))
  for (const chunk of chunks) {
    const lines = chunk.replace(/\r\n/g, '\n').split('\n')
    const firstHunk = lines.findIndex(line => line.startsWith('@@'))
    const header = firstHunk === -1 ? lines : lines.slice(0, firstHunk)
    const body = firstHunk === -1 ? [] : lines.slice(firstHunk)

    // The new path from `+++ b/…`, the old one from `--- a/…` for a deletion; else the header's.
    const after = header.find(line => line.startsWith('+++ b/'))?.slice('+++ b/'.length)
    const before = header.find(line => line.startsWith('--- a/'))?.slice('--- a/'.length)
    const renamed = header.find(line => line.startsWith('rename to '))?.slice('rename to '.length)
    const fromHeader = / b\/(.*)$/.exec(lines[0] ?? '')?.[1] ?? ''
    const path = after ?? renamed ?? before ?? fromHeader

    const status: ChangedFile['status'] = header.some(line => line.startsWith('new file mode'))
      ? 'A'
      : header.some(line => line.startsWith('deleted file mode'))
        ? 'D'
        : renamed !== undefined
          ? 'R'
          : 'M'
    const isBinary = header.some(line => line.startsWith('Binary files '))

    let added = 0
    let removed = 0
    for (const line of body) {
      if (line.startsWith('+')) added += 1
      else if (line.startsWith('-')) removed += 1
    }

    // Whole hunks while they fit what is left; once one does not, none after it.
    const hunks: string[] = []
    for (const hunk of body.join('\n').split(/^(?=@@)/m)) {
      if (!hunk.startsWith('@@')) continue
      if (isCut || used + hunk.length > limit) {
        isCut = true
        break
      }
      hunks.push(hunk)
      used += hunk.length
    }
    files.push({ path, status, added, removed, hunks: hunks.join('').replace(/\n+$/, ''), isBinary })
  }
  return { files, isCut }
}

files.hooks/host.ts:
// The folder menu's actions as programs of the machine: its file manager, VS Code and a terminal
// opened in the folder. Each returns at once, so `$.process.run` never waits on the window.

import type { HostTools } from '../types'

export type FolderAction = 'files' | 'code' | 'terminal' | 'copy'
export type MenuItem = { action: FolderAction; label: string }

export function fileManager(platform: HostTools['platform']): string {
  return platform === 'windows' ? 'Explorer' : platform === 'mac' ? 'Finder' : 'file manager'
}

// The menu, in order; VS Code only where its command is found.
export function menuItems(host: HostTools): MenuItem[] {
  return [
    { action: 'files', label: `Open in ${fileManager(host.platform)}` },
    ...(host.hasCode ? [{ action: 'code' as const, label: 'Open in VS Code' }] : []),
    { action: 'terminal', label: 'Open a terminal here' },
    { action: 'copy', label: 'Copy path' },
  ]
}

// The program an action runs, and the folder it runs in; undefined for the copy, done in place.
export function actionArgv(action: FolderAction, host: HostTools, folder: string): { argv: string[]; cwd?: string } | undefined {
  // Explorer reads a path with forward slashes as none and opens Documents.
  const path = host.platform === 'windows' ? folder.replace(/\//g, '\\') : folder
  if (action === 'files') {
    return { argv: host.platform === 'windows' ? ['explorer.exe', path] : [host.platform === 'mac' ? 'open' : 'xdg-open', path] }
  }
  if (action === 'code') {
    // `code` is a .cmd on Windows, which only cmd starts.
    return { argv: host.platform === 'windows' ? ['cmd.exe', '/d', '/c', 'code', path] : ['code', path] }
  }
  if (action === 'terminal') {
    if (host.platform === 'windows') {
      return { argv: host.hasWt ? ['wt.exe', '-d', path] : ['cmd.exe', '/d', '/c', 'start', '', '/D', path, 'cmd.exe'] }
    }
    if (host.platform === 'mac') return { argv: ['open', '-a', 'Terminal', path] }
    // Detached, so the call returns while the terminal stays open.
    return { argv: ['sh', '-c', 'nohup x-terminal-emulator >/dev/null 2>&1 &'], cwd: path }
  }
  return undefined
}

files.hooks/settings.ts:
// The person's choices from /config (the manifest's userConfig): which of the band's parts show,
// and how the prompt cache and the thresholds speak up. The defaults are the band as it always was.

export type Settings = {
  /** `full`: branch, files changed (with their diff), ahead/behind, stashes, an operation under way and its
   *  conflicts; `branch`: the branch and an operation under way with its conflicts; `off`: the folder alone. */
  git: 'full' | 'branch' | 'off'
  /** `auto`: the 5h/7d rate limits on a subscription, the cost on an API account. */
  usage: 'auto' | 'rate-limits' | 'cost' | 'off'
  /** `ask`: the countdown, and a prompt over a cold cache held with a question; `warn`: the
   *  countdown and a toast; `off`: neither. */
  cache: 'ask' | 'warn' | 'off'
  /** The context and rate-limit thresholds: `critical` only the red ones. */
  toasts: 'all' | 'critical' | 'off'
}

export const DEFAULT_SETTINGS: Settings = { git: 'full', usage: 'auto', cache: 'ask', toasts: 'all' }

export const CHOICES = {
  git: ['full', 'branch', 'off'],
  usage: ['auto', 'rate-limits', 'cost', 'off'],
  cache: ['ask', 'warn', 'off'],
  toasts: ['all', 'critical', 'off'],
} as const

function pick<K extends keyof typeof CHOICES>(options: Readonly<Record<string, unknown>>, key: K): Settings[K] {
  const value = options[key]
  return (CHOICES[key] as readonly unknown[]).includes(value) ? (value as Settings[K]) : DEFAULT_SETTINGS[key]
}

// The engine fills the defaults and drops a value outside a field's options; this keeps the band
// whole even so.
export function readSettings(options: Readonly<Record<string, unknown>> = {}): Settings {
  return {
    git: pick(options, 'git'),
    usage: pick(options, 'usage'),
    cache: pick(options, 'cache'),
    toasts: pick(options, 'toasts'),
  }
}

export type SettingKey = keyof typeof CHOICES

// The settings menu's rows, in order, by the name the person reads.
export const SETTING_ROWS: readonly { key: SettingKey; label: string }[] = [
  { key: 'git', label: 'Git' },
  { key: 'usage', label: 'Usage' },
  { key: 'cache', label: 'Prompt cache' },
  { key: 'toasts', label: 'Toasts' },
]

// A press on a row moves it to its next value, the last one back to the first.
export function nextValue(key: SettingKey, current: string): string {
  const choices: readonly string[] = CHOICES[key]
  return choices[(choices.indexOf(current) + 1) % choices.length] ?? choices[0] ?? current
}

// The lowest level of a threshold that toasts: 1 orange and red, 2 red alone.
export function toastLevel(toasts: Settings['toasts']): number {
  return toasts === 'all' ? 1 : toasts === 'critical' ? 2 : Infinity
}

